class CAriaRSIReader
{
private:
    int         m_handle;
    int         m_period;
    string      m_symbol;
    ENUM_TIMEFRAMES m_timeframe;

public:
    CAriaRSIReader() : m_handle(INVALID_HANDLE), m_period(14), m_symbol(""), m_timeframe(PERIOD_M15) {}
    ~CAriaRSIReader() { Release(); }

    bool Init(const string symbol, const ENUM_TIMEFRAMES tf = PERIOD_M15, const int period = 14)
    {
        m_symbol = symbol;
        m_timeframe = tf;
        m_period = period;
        m_handle = iRSI(m_symbol, m_timeframe, m_period, PRICE_CLOSE);
        if(m_handle == INVALID_HANDLE)
        {
            PrintFormat("[ERROR] Failed to create iRSI handle for %s. Error: %d", m_symbol, GetLastError());
            return false;
        }
        return true;
    }

    void Release()
    {
        if(m_handle != INVALID_HANDLE)
        {
            IndicatorRelease(m_handle);
            m_handle = INVALID_HANDLE;
        }
    }

    bool GetRecentRSI(double &rsi_1, double &rsi_2)
    {
        if(m_handle == INVALID_HANDLE) return false;
        double buf[2];
        if(CopyBuffer(m_handle, 0, 1, 2, buf) < 2)
            return false;
        rsi_1 = buf[1]; // bar 1 (most recently closed)
        rsi_2 = buf[0]; // bar 2
        return true;
    }
};
