class CRingBufferDouble
{
private:
    double   m_data[];
    int      m_capacity;
    int      m_head;
    int      m_count;

public:
    CRingBufferDouble() : m_capacity(0), m_head(0), m_count(0) {}

    void Init(const int capacity)
    {
        m_capacity = capacity;
        ArrayResize(m_data, capacity);
        ArrayInitialize(m_data, 0.0);
        m_head = 0;
        m_count = 0;
    }

    void Push(const double value)
    {
        m_data[m_head] = value;
        m_head = (m_head + 1) % m_capacity;
        if(m_count < m_capacity) m_count++;
    }

    double Get(const int offset_from_newest) const
    {
        if(offset_from_newest >= m_count) return 0.0;
        int idx = (m_head - 1 - offset_from_newest + m_capacity * 2) % m_capacity;
        return m_data[idx];
    }

    int Count() const { return m_count; }
};
