#include <Trade\PositionInfo.mqh>
#include <Trade\Trade.mqh>

CPositionInfo m_pos;
CTrade        m_trade_exec;

void CheckAndApplyBreakEven(const string symbol, const ulong magic, const double trigger_points, const double lock_points)
{
    for(int i = PositionsTotal() - 1; i >= 0; i--)
    {
        if(!m_pos.SelectByIndex(i)) continue;
        if(m_pos.Symbol() != symbol || m_pos.Magic() != magic) continue;

        double open_price = m_pos.PriceOpen();
        double current_price = m_pos.PriceCurrent();
        double sl = m_pos.StopLoss();
        double point = SymbolInfoDouble(symbol, SYMBOL_POINT);

        if(m_pos.PositionType() == POSITION_TYPE_BUY)
        {
            if(current_price - open_price >= trigger_points * point)
            {
                double target_sl = open_price + lock_points * point;
                if(sl < target_sl)
                {
                    m_trade_exec.PositionModify(m_pos.Ticket(), target_sl, m_pos.TakeProfit());
                    PrintFormat("[BREAKEVEN] Buy position #%d locked at %.5f", m_pos.Ticket(), target_sl);
                }
            }
        }
        else if(m_pos.PositionType() == POSITION_TYPE_SELL)
        {
            if(open_price - current_price >= trigger_points * point)
            {
                double target_sl = open_price - lock_points * point;
                if(sl == 0.0 || sl > target_sl)
                {
                    m_trade_exec.PositionModify(m_pos.Ticket(), target_sl, m_pos.TakeProfit());
                    PrintFormat("[BREAKEVEN] Sell position #%d locked at %.5f", m_pos.Ticket(), target_sl);
                }
            }
        }
    }
}
