bool GetM15ClosePrices(const string symbol, const int count, double &out_prices[])
{
    MqlRates rates[];
    ArraySetAsSeries(rates, true);

    ResetLastError();
    int copied = CopyRates(symbol, PERIOD_M15, 1, count, rates);
    if(copied < count)
    {
        PrintFormat("[WARN] CopyRates incomplete for %s M15: copied %d of %d (err: %d)", symbol, copied, count, GetLastError());
        return false;
    }

    ArrayResize(out_prices, count);
    for(int i = 0; i < count; i++)
    {
        out_prices[i] = rates[i].close;
    }
    return true;
}
